parameters.jsCode:
const text = ($json.merged_response ?? ($json.content && $json.content.find(c => c.type === 'text') ? $json.content.find(c => c.type === 'text').text : '') ?? '').trim();
const raw = text.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '').trim();
let parsed = null;
try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }
return {
  json: {
    valid: parsed !== null,
    root_cause_summary: (parsed && parsed.root_cause_summary) || 'Unable to determine the root cause automatically.',
    spoken_explanation: (parsed && parsed.spoken_explanation) || 'Sorry, I could not analyze this error automatically. Please review the raw error log for details.',
    terminal_fix_command: (parsed && parsed.terminal_fix_command) || '',
    cursor_prompt: (parsed && parsed.cursor_prompt) || '',
    raw_text: text,
  },
};

const a = $('Analysis').item.json;
let audio_url = null;
try {
  const item = $input.item;
  const binKey = item.binary && Object.keys(item.binary)[0];
  if (binKey) {
    const buf = await this.helpers.getBinaryDataBuffer(0, binKey);
    if (buf && buf.length) {
      audio_url = 'data:audio/mpeg;base64,' + Buffer.from(buf).toString('base64');
    }
  }
} catch (e) {
  audio_url = null;
}
return {
  json: {
    root_cause_summary: a.root_cause_summary,
    spoken_explanation: a.spoken_explanation,
    terminal_fix_command: a.terminal_fix_command,
    cursor_prompt: a.cursor_prompt,
    audio_url,
  },
};
